}
import { Router } from "express";
import { z } from "zod";
import { ACTIVITIES, INTERESTS, MINIMUM_MEETING_MINUTES, STUDENT_TYPES, type Profile } from "../domain/types.js";
import { now, type MemoryStore } from "../store.js";
import { currentUserId } from "./auth.js";
import { ApiError, asyncRoute } from "./errors.js";

const profileInput = z.object({
  schoolId: z.string().min(1), campusId: z.string().min(1), nickname: z.string(), major: z.string().trim().min(1).max(100), grade: z.enum(["1", "2", "3", "4", "OTHER"]),
  studentType: z.enum(STUDENT_TYPES), activities: z.array(z.enum(ACTIVITIES)).min(1), interests: z.array(z.enum(INTERESTS)).min(1).max(10),
  languages: z.object({ speaks: z.array(z.string().min(1).max(10)).max(10), learning: z.array(z.string().min(1).max(10)).max(10) })
});
const preferenceInput = z.object({ isDiscoverable: z.boolean(), minimumMeetingMinutes: z.union(MINIMUM_MEETING_MINUTES.map((value) => z.literal(value)) as [z.ZodLiteral<30>, z.ZodLiteral<60>, z.ZodLiteral<90>, z.ZodLiteral<120>]) });

function profileResponse(store: MemoryStore, profile: Profile) {
  const school = store.getSchool(profile.schoolId)!;
  const campus = store.getCampus(profile.campusId)!;
  return { userId: profile.userId, school: { id: school.id, name: school.name }, campus: { id: campus.id, name: campus.name }, nickname: profile.nickname, major: profile.major, grade: profile.grade, studentType: profile.studentType, activities: profile.activities, interests: profile.interests, languages: profile.languages, isComplete: true, updatedAt: profile.updatedAt };
}

export function createProfileRouter(store: MemoryStore): Router {
  const router = Router();
  router.get("/schools", (_request, response) => response.json({ data: store.schools.map(({ id, name }) => ({ id, name })) }));
  router.get("/schools/:schoolId/campuses", (request, response) => {
    if (!store.getSchool(request.params.schoolId)) throw new ApiError(404, "SCHOOL_NOT_FOUND", "학교를 찾을 수 없습니다.");
    response.json({ data: store.campusesForSchool(request.params.schoolId).map(({ id, schoolId, name, timeZone }) => ({ id, schoolId, name, timeZone })) });
  });
  router.get("/profile-options", (_request, response) => response.json({ data: { grades: ["1", "2", "3", "4", "OTHER"], studentTypes: STUDENT_TYPES, activities: ACTIVITIES, interests: INTERESTS, minimumMeetingMinutes: MINIMUM_MEETING_MINUTES } }));
  router.get("/me/profile", (request, response) => {
    const profile = store.getProfile(currentUserId(request));
    if (!profile) throw new ApiError(404, "PROFILE_NOT_FOUND", "프로필을 찾을 수 없습니다.");
    response.json({ data: profileResponse(store, profile) });
  });
  router.put("/me/profile", asyncRoute((request, response) => {
    const userId = currentUserId(request);
    const input = profileInput.parse(request.body);
    const nickname = input.nickname.trim();
    if (nickname.length < 2 || nickname.length > 20) throw new ApiError(422, "VALIDATION_ERROR", "입력값을 확인해 주세요.", [{ field: "nickname", reason: "닉네임은 2~20자여야 합니다." }]);
    const campus = store.getCampus(input.campusId);
    if (!store.getSchool(input.schoolId) || !campus || campus.schoolId !== input.schoolId) throw new ApiError(422, "INVALID_SCHOOL_CAMPUS", "학교와 캠퍼스 관계가 유효하지 않습니다.");
    if (!input.activities.includes("LUNCH")) throw new ApiError(422, "VALIDATION_ERROR", "입력값을 확인해 주세요.", [{ field: "activities", reason: "LUNCH 활동은 필수입니다." }]);
    if (input.activities.includes("LANGUAGE_EXCHANGE") && input.languages.speaks.length + input.languages.learning.length === 0) throw new ApiError(422, "VALIDATION_ERROR", "입력값을 확인해 주세요.", [{ field: "languages", reason: "언어교환 활동에는 언어 정보가 필요합니다." }]);
    if (store.nicknameTaken(nickname, userId)) throw new ApiError(409, "NICKNAME_ALREADY_EXISTS", "이미 사용 중인 닉네임입니다.");
    const profile = store.saveProfile({ ...input, nickname, userId, updatedAt: now() });
    response.json({ data: profileResponse(store, profile) });
  }));
  router.get("/me/match-preferences", (request, response) => { const { userId: _userId, ...preference } = store.getPreference(currentUserId(request)); response.json({ data: preference }); });
  router.put("/me/match-preferences", (request, response) => { const input = preferenceInput.parse(request.body); const { userId: _userId, ...preference } = store.savePreference({ ...input, userId: currentUserId(request), updatedAt: now() }); response.json({ data: preference }); });
  return router;
}
import { Router } from "express";
import { z } from "zod";
import { DAYS, type DayOfWeek, type PreferredSlot, type Schedule } from "../domain/types.js";
import { calculateEffectiveSlots, calculateFreeSlots, mergePreferredSlots, parseTime, SERVICE_END, SERVICE_START } from "../domain/time.js";
import { now, type MemoryStore } from "../store.js";
import { currentUserId } from "./auth.js";
import { ApiError } from "./errors.js";

const scheduleInput = z.object({ dayOfWeek: z.enum(DAYS), subjectName: z.string().trim().min(1).max(100), startTime: z.string(), endTime: z.string(), classroom: z.string().trim().max(100).nullable() });
const schedulePatch = scheduleInput.partial();
const availabilityInput = z.object({ preferredSlots: z.array(z.object({ dayOfWeek: z.enum(DAYS), startTime: z.string(), endTime: z.string() })).max(50) });

function validateTimeRange(startTime: string, endTime: string, isWithinServiceWindow: boolean): void {
  const start = parseTime(startTime);
  const end = parseTime(endTime);
  if (start === null || end === null || start >= end) throw new ApiError(422, "INVALID_TIME_RANGE", "시작 시각은 종료 시각보다 빨라야 합니다.");
  if (start % 30 !== 0 || end % 30 !== 0) throw new ApiError(422, "INVALID_TIME_UNIT", "시각은 30분 단위여야 합니다.");
  if (isWithinServiceWindow && (start < SERVICE_START || end > SERVICE_END)) throw new ApiError(422, "INVALID_TIME_RANGE", "선호 시간은 11:00~15:00 범위여야 합니다.");
}

function hasOverlap(candidate: Pick<Schedule, "dayOfWeek" | "startTime" | "endTime">, schedules: Schedule[]): boolean {
  const candidateStart = parseTime(candidate.startTime)!;
  const candidateEnd = parseTime(candidate.endTime)!;
  return schedules.some((schedule) => schedule.dayOfWeek === candidate.dayOfWeek && candidateStart < parseTime(schedule.endTime)! && parseTime(schedule.startTime)! < candidateEnd);
}

function availabilityResponse(store: MemoryStore, userId: string) {
  const preferredSlots = store.getAvailability(userId);
  const effectiveSlots = calculateEffectiveSlots(calculateFreeSlots(store.listSchedules(userId), 30), preferredSlots);
  return { preferredSlots, effectiveSlots, updatedAt: store.getAvailabilityUpdatedAt(userId) };
}

export function createScheduleRouter(store: MemoryStore): Router {
  const router = Router();
  router.get("/me/schedules", (request, response) => response.json({ data: store.listSchedules(currentUserId(request)) }));
  router.post("/me/schedules", (request, response) => {
    const userId = currentUserId(request);
    const input = scheduleInput.parse(request.body);
    validateTimeRange(input.startTime, input.endTime, false);
    if (hasOverlap(input, store.listSchedules(userId))) throw new ApiError(409, "SCHEDULE_TIME_OVERLAP", "같은 요일의 수업 시간이 겹칩니다.");
    const schedule = store.createSchedule({ ...input, userId });
    response.location(`/api/v1/me/schedules/${schedule.id}`).status(201).json({ data: schedule });
  });
  router.patch("/me/schedules/:scheduleId", (request, response) => {
    const userId = currentUserId(request);
    const current = store.listSchedules(userId).find((schedule) => schedule.id === request.params.scheduleId);
    if (!current) throw new ApiError(404, "SCHEDULE_NOT_FOUND", "수업을 찾을 수 없습니다.");
    const update = schedulePatch.parse(request.body);
    const candidate = { ...current, ...update };
    validateTimeRange(candidate.startTime, candidate.endTime, false);
    if (hasOverlap(candidate, store.listSchedules(userId).filter((schedule) => schedule.id !== current.id))) throw new ApiError(409, "SCHEDULE_TIME_OVERLAP", "같은 요일의 수업 시간이 겹칩니다.");
    response.json({ data: store.updateSchedule(current.id, update)! });
  });
  router.delete("/me/schedules/:scheduleId", (request, response) => {
    const current = store.listSchedules(currentUserId(request)).find((schedule) => schedule.id === request.params.scheduleId);
    if (!current) throw new ApiError(404, "SCHEDULE_NOT_FOUND", "수업을 찾을 수 없습니다.");
    store.deleteSchedule(current.id);
    response.status(204).end();
  });
  router.get("/me/free-times", (request, response) => {
    const rawMinimum = request.query.minimumMinutes ?? "30";
    const minimumMinutes = typeof rawMinimum === "string" ? Number(rawMinimum) : Number.NaN;
    if (!Number.isInteger(minimumMinutes) || minimumMinutes < 30 || minimumMinutes % 30 !== 0) throw new ApiError(422, "VALIDATION_ERROR", "minimumMinutes는 30분 이상의 30분 단위여야 합니다.");
    response.json({ data: { serviceWindow: { startTime: "11:00", endTime: "15:00", timeZone: "Asia/Seoul" }, slots: calculateFreeSlots(store.listSchedules(currentUserId(request)), minimumMinutes), calculatedAt: now() } });
  });
  router.get("/me/availability", (request, response) => response.json({ data: availabilityResponse(store, currentUserId(request)) }));
  router.put("/me/availability", (request, response) => {
    const userId = currentUserId(request);
    const input = availabilityInput.parse(request.body);
    input.preferredSlots.forEach((slot) => validateTimeRange(slot.startTime, slot.endTime, true));
    const slots: PreferredSlot[] = mergePreferredSlots(input.preferredSlots);
    store.saveAvailability(userId, slots);
    response.json({ data: availabilityResponse(store, userId) });
  });
  return router;
}
import type { CoreQueryPort } from "./domain/core-query-port.js";
import { calculateEffectiveSlots, calculateFreeSlots } from "./domain/time.js";
import type { TimeSlot, UserMatchView } from "./domain/types.js";
import type { MemoryStore } from "./store.js";
import { ApiError } from "./http/errors.js";

export class StoreCoreQueryPort implements CoreQueryPort {
  constructor(private readonly store: MemoryStore) {}

  async getUserMatchView(userId: string): Promise<UserMatchView> {
    const profile = this.store.getProfile(userId);
    const user = this.store.getUser(userId);
    const campus = profile && this.store.getCampus(profile.campusId);
    if (!profile || !user || !campus) throw new ApiError(404, "PROFILE_NOT_FOUND", "프로필을 찾을 수 없습니다.");
    const preference = this.store.getPreference(userId);
    return { userId, nickname: profile.nickname, grade: profile.grade, schoolId: profile.schoolId, campusId: profile.campusId, campusName: campus.name, activities: [...profile.activities], interests: [...profile.interests], languages: { speaks: [...profile.languages.speaks], learning: [...profile.languages.learning] }, isDiscoverable: preference.isDiscoverable, minimumMeetingMinutes: preference.minimumMeetingMinutes, isActive: user.isActive };
  }

  async listDiscoverableCampusUsers(campusId: string, excludeUserId: string): Promise<UserMatchView[]> {
    const profiles = this.store.listProfilesAtCampus(campusId).filter((profile) => profile.userId !== excludeUserId);
    const views = await Promise.all(profiles.map((profile) => this.getUserMatchView(profile.userId)));
    return views.filter((view) => view.isDiscoverable && view.isActive);
  }

  async getEffectiveSlots(userId: string): Promise<TimeSlot[]> {
    return calculateEffectiveSlots(calculateFreeSlots(this.store.listSchedules(userId), 30), this.store.getAvailability(userId));
  }
}
import { createApp } from "./app.js";

const port = Number(process.env.PORT ?? 3000);

createApp().listen(port, () => {
  console.info(`Backend listening on port ${port}`);
});

