import { Pool } from "pg";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) throw new Error("DATABASE_URL is required. Run npm run migrate first.");
const pool = new Pool({ connectionString: databaseUrl });

try {
  await pool.query("BEGIN");
  await pool.query("INSERT INTO schools (id,name) VALUES ('school_yonsei','연세대학교') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name");
  await pool.query("INSERT INTO campuses (id,school_id,name) VALUES ('campus_yonsei_sinchon','school_yonsei','신촌캠퍼스') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name");
  await pool.query("INSERT INTO users (id) VALUES ('user_a'),('user_b'),('user_c') ON CONFLICT (id) DO NOTHING");

  for (const [userId, nickname, interests] of [["user_a", "민지", ["MUSIC", "TRAVEL"]], ["user_b", "Alex", ["MUSIC", "FOOD"]], ["user_c", "지호", ["GAMES"]]] as const) {
    await pool.query("INSERT INTO profiles (user_id,school_id,campus_id,nickname,major,grade,student_type,activities,interests,languages,updated_at) VALUES ($1,'school_yonsei','campus_yonsei_sinchon',$2,'컴퓨터과학과','3','DOMESTIC',ARRAY['LUNCH'],$3,$4,NOW()) ON CONFLICT (user_id) DO UPDATE SET school_id=EXCLUDED.school_id,campus_id=EXCLUDED.campus_id,nickname=EXCLUDED.nickname,major=EXCLUDED.major,grade=EXCLUDED.grade,student_type=EXCLUDED.student_type,activities=EXCLUDED.activities,interests=EXCLUDED.interests,languages=EXCLUDED.languages,updated_at=EXCLUDED.updated_at", [userId, nickname, interests, JSON.stringify({ speaks: [], learning: [] })]);
    await pool.query("INSERT INTO match_preferences (user_id,is_discoverable,minimum_meeting_minutes,updated_at) VALUES ($1,true,60,NOW()) ON CONFLICT (user_id) DO UPDATE SET is_discoverable=EXCLUDED.is_discoverable,minimum_meeting_minutes=EXCLUDED.minimum_meeting_minutes,updated_at=EXCLUDED.updated_at", [userId]);
  }

  await pool.query("DELETE FROM availability_slots WHERE user_id IN ('user_a','user_b','user_c')");
  await pool.query("INSERT INTO availability_slots (user_id,day_of_week,start_time,end_time) VALUES ('user_a','MONDAY','12:00','14:00'),('user_b','MONDAY','12:00','13:30'),('user_c','MONDAY','11:00','12:00')");
  await pool.query("INSERT INTO availability_updates (user_id,updated_at) VALUES ('user_a',NOW()),('user_b',NOW()),('user_c',NOW()) ON CONFLICT (user_id) DO UPDATE SET updated_at=EXCLUDED.updated_at");

  for (const venue of [
    ["venue_student_hall", "학생회관 식당", "RESTAURANT", 3, "UNDER_10000", ["QUICK_MEAL"], "캠퍼스 안에서 빠르게 식사할 수 있는 장소"],
    ["venue_rice_bowl", "캠퍼스 앞 덮밥집", "RESTAURANT", 6, "UNDER_10000", ["GOOD_FOR_TALKING"], "든든한 한 끼를 먹기 좋은 식당"],
    ["venue_campus_cafe", "캠퍼스 카페", "CAFE", 4, "AROUND_15000", ["GOOD_FOR_TALKING", "RELAXED"], "식사 후 대화하기 좋은 카페"]
  ] as const) {
    const [id, name, category, walkMinutes, priceRange, tags, description] = venue;
    await pool.query("INSERT INTO venues (id,campus_id,name,category,walk_minutes,price_range,tags,description,is_active) VALUES ($1,'campus_yonsei_sinchon',$2,$3,$4,$5,$6,$7,true) ON CONFLICT (id) DO UPDATE SET campus_id=EXCLUDED.campus_id,name=EXCLUDED.name,category=EXCLUDED.category,walk_minutes=EXCLUDED.walk_minutes,price_range=EXCLUDED.price_range,tags=EXCLUDED.tags,description=EXCLUDED.description,is_active=true", [id, name, category, walkMinutes, priceRange, [...tags], description]);
  }
  await pool.query("COMMIT");
} catch (error) {
  await pool.query("ROLLBACK");
  throw error;
} finally {
  await pool.end();
}

console.info("Seed complete.");
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS schools (id TEXT PRIMARY KEY, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS campuses (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, time_zone TEXT NOT NULL DEFAULT 'Asia/Seoul', is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, school_id TEXT NOT NULL REFERENCES schools(id), campus_id TEXT NOT NULL REFERENCES campuses(id), nickname TEXT NOT NULL UNIQUE, major TEXT NOT NULL, grade TEXT NOT NULL, student_type TEXT NOT NULL, activities TEXT[] NOT NULL, interests TEXT[] NOT NULL, languages JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS match_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, is_discoverable BOOLEAN NOT NULL DEFAULT true, minimum_meeting_minutes SMALLINT NOT NULL CHECK (minimum_meeting_minutes IN (30,60,90,120)), updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS class_schedules (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day_of_week TEXT NOT NULL CHECK (day_of_week IN ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY')), subject_name TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, classroom TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS availability_slots (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day_of_week TEXT NOT NULL CHECK (day_of_week IN ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY')), start_time TEXT NOT NULL, end_time TEXT NOT NULL, PRIMARY KEY (user_id, day_of_week, start_time, end_time));
CREATE TABLE IF NOT EXISTS availability_updates (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_profiles_campus ON profiles(campus_id);
CREATE INDEX IF NOT EXISTS idx_schedules_user_day ON class_schedules(user_id, day_of_week, start_time);
CREATE TABLE IF NOT EXISTS venues (
  id TEXT PRIMARY KEY,
  campus_id TEXT NOT NULL REFERENCES campuses(id),
  name TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('RESTAURANT','CAFE','STUDY_SPACE')),
  walk_minutes SMALLINT NOT NULL CHECK (walk_minutes >= 0),
  price_range TEXT NOT NULL CHECK (price_range IN ('UNDER_10000','AROUND_15000','FLEXIBLE')),
  tags TEXT[] NOT NULL DEFAULT '{}',
  description TEXT NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS meeting_proposals (
  id TEXT PRIMARY KEY,
  sender_id TEXT NOT NULL REFERENCES users(id),
  receiver_id TEXT NOT NULL REFERENCES users(id),
  meeting_date DATE NOT NULL,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  activity TEXT NOT NULL CHECK (activity = 'LUNCH'),
  venue_type TEXT NOT NULL CHECK (venue_type IN ('RECOMMENDED','CUSTOM')),
  venue_id TEXT NULL REFERENCES venues(id),
  venue_name TEXT NOT NULL,
  venue_walk_minutes SMALLINT NULL,
  venue_price_range TEXT NULL CHECK (venue_price_range IN ('UNDER_10000','AROUND_15000','FLEXIBLE')),
  message TEXT NULL,
  status TEXT NOT NULL CHECK (status IN ('PENDING','ACCEPTED','REJECTED','CANCELED')),
  created_at TIMESTAMPTZ NOT NULL,
  responded_at TIMESTAMPTZ NULL,
  canceled_by TEXT NULL REFERENCES users(id),
  CHECK (sender_id <> receiver_id),
  CHECK ((venue_type = 'RECOMMENDED' AND venue_id IS NOT NULL AND venue_walk_minutes IS NOT NULL AND venue_price_range IS NOT NULL) OR (venue_type = 'CUSTOM' AND venue_id IS NULL AND venue_walk_minutes IS NULL AND venue_price_range IS NULL))
);

CREATE INDEX IF NOT EXISTS idx_venues_campus_active ON venues(campus_id) WHERE is_active = true;
CREATE INDEX IF NOT EXISTS idx_meeting_proposals_participant_date ON meeting_proposals(sender_id, meeting_date);
CREATE INDEX IF NOT EXISTS idx_meeting_proposals_receiver_date ON meeting_proposals(receiver_id, meeting_date);
CREATE UNIQUE INDEX IF NOT EXISTS uq_pending_proposal_pair_time ON meeting_proposals (LEAST(sender_id, receiver_id), GREATEST(sender_id, receiver_id), meeting_date, start_time, end_time) WHERE status = 'PENDING';
export const DAYS = ["MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY"] as const;
export const ACTIVITIES = ["LUNCH", "CAFE", "STUDY", "LANGUAGE_EXCHANGE", "EXERCISE", "HOBBY", "CAMPUS_TOUR", "MAKE_FRIENDS"] as const;
export const INTERESTS = ["MUSIC", "TRAVEL", "MOVIES", "BOOKS", "GAMES", "SPORTS", "FOOD", "CULTURE", "TECH", "CAREER"] as const;
export const STUDENT_TYPES = ["DOMESTIC", "INTERNATIONAL", "EXCHANGE", "OTHER"] as const;
export const MINIMUM_MEETING_MINUTES = [30, 60, 90, 120] as const;
export const VENUE_CATEGORIES = ["RESTAURANT", "CAFE", "STUDY_SPACE"] as const;
export const PRICE_RANGES = ["UNDER_10000", "AROUND_15000", "FLEXIBLE"] as const;
export const ATMOSPHERES = ["QUICK_MEAL", "GOOD_FOR_TALKING", "RELAXED"] as const;
export const PROPOSAL_STATUSES = ["PENDING", "ACCEPTED", "REJECTED", "CANCELED"] as const;

export type DayOfWeek = (typeof DAYS)[number];
export type TimeSlot = { dayOfWeek: DayOfWeek; startTime: string; endTime: string; durationMinutes: number };
export type PreferredSlot = Omit<TimeSlot, "durationMinutes">;
export type User = { id: string; isActive: boolean };
export type Profile = { userId: string; schoolId: string; campusId: string; nickname: string; major: string; grade: string; studentType: (typeof STUDENT_TYPES)[number]; activities: string[]; interests: string[]; languages: { speaks: string[]; learning: string[] }; updatedAt: string };
export type MatchPreference = { userId: string; isDiscoverable: boolean; minimumMeetingMinutes: number; updatedAt: string };
export type Schedule = { id: string; userId: string; dayOfWeek: DayOfWeek; subjectName: string; startTime: string; endTime: string; classroom: string | null; createdAt: string; updatedAt: string };
export type School = { id: string; name: string; isActive: boolean };
export type Campus = { id: string; schoolId: string; name: string; timeZone: "Asia/Seoul"; isActive: boolean };

export type Venue = {
  id: string;
  campusId: string;
  name: string;
  category: (typeof VENUE_CATEGORIES)[number];
  walkMinutes: number;
  priceRange: (typeof PRICE_RANGES)[number];
  tags: string[];
  description: string;
  isActive: boolean;
};

export type ProposalVenue = {
  type: "RECOMMENDED" | "CUSTOM";
  venueId: string | null;
  name: string;
  walkMinutes: number | null;
  priceRange: (typeof PRICE_RANGES)[number] | null;
};

export type ProposalStatus = (typeof PROPOSAL_STATUSES)[number];

export type MeetingProposal = {
  id: string;
  senderId: string;
  receiverId: string;
  date: string;
  startTime: string;
  endTime: string;
  activity: "LUNCH";
  venue: ProposalVenue;
  message: string | null;
  status: ProposalStatus;
  createdAt: string;
  respondedAt: string | null;
  canceledBy: string | null;
};

export type UserMatchView = { userId: string; nickname: string; grade: string; schoolId: string; campusId: string; campusName: string; activities: string[]; interests: string[]; languages: { speaks: string[]; learning: string[] }; isDiscoverable: boolean; minimumMeetingMinutes: number; isActive: boolean };
